function CountOddLowerCaseLetters(txt: string): int
    requires txt != null
    ensures 0 <= result <= |txt| // result is the count of lowercase letters in odd positions
{
    var count := 0;
    var i := 0;
    while i < |txt|
        invariant 0 <= count <= i // count is valid at each step
        invariant 0 <= i <= |txt|
    {
        if txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2 == 1) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
